WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_current_calc'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '现期量计算', 'kp-xingce-data-current-calc', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "现期量计算"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知历史基数和变化幅度，正向推导当前数值的计算。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干给的是“2022年数据”和“同比增长率”，问的是“2023年数据”。这是最符合人类正向思维的题型。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "现期量 = 基期量 \\times (1 + 增长率)"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[明确题意求现期量] --> B[定位基期量和增长率 r]\nB --> C{r 是正是负?}\nC -- 正增长 --> D[现期量 = 基期量 + 基期量 × r]\nC -- 负增长 --> E[现期量 = 基期量 - 基期量 × |r|]\nD --> F[计算尾部乘积并与基期量相加/相减]\nE --> F"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2022年某省产值 3450 亿元，2023年增长了 11%。求2023年产值约是多少？选项：A. 3720  B. 3830  C. 3940  D. 4100"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别公式：现期量 = 3450 × (1 + 11%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "乘法拆分：不要硬算竖式，将其拆分为：3450 + 3450 × 10% + 3450 × 1%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "口算各项：3450 × 10% = 345；3450 × 1% = 34.5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "汇总加和：3450 + 345 + 34.5 = 3829.5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：最接近的是 B (3830)。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "负增长率强行做加法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "当题目说“下降了 8%”时，很多考生列式对了 3450 × (1-8%)，但拆分计算时习惯性写成了 3450 + 3450×8%。下降必须是减法！一定要在草稿纸上把减号画粗！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "专门训练乘法拆分。看到 12% 就要立刻想到 10% + 2%，看到 9% 就要想到 10% - 1%。把繁琐的两位数乘法变成简单的小数点移位加减。"}]}]}$$ AS jsonb), NULL, '现期量计算的核心考点与实战推导。', category_node.id, CAST('["资料分析", "现期量计算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_current_calc", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
